static int mountcontext(int rw){FILE*f=fopen("/proc/mounts","r");if(!f)return -1;int r=mount_table(f,rw);if(fclose(f))r=-1;return r;}
static int upgrade_blob(const char*path,unsigned char*b,size_t cap,size_t*len){int fd=open(path,O_RDONLY|O_NOFOLLOW|O_CLOEXEC);if(fd<0)return -1;ssize_t n=read(fd,b,cap);close(fd);if(n<0||(size_t)n==cap)return -1;*len=(size_t)n;return 0;}
